namespace sv_5d4d0f78b60f4a24b020e98e7b6c6c10.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service that tracks the currently selected warehouse per circuit.
/// Components subscribe to OnChange to react when the selection changes.
/// </summary>
public class WarehouseState
{
    private string _selectedWarehouseId = "wh-1";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public event Action? OnChange;

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "wh-1", Name = "Warehouse A — Downtown" },
        new() { Id = "wh-2", Name = "Warehouse B — Airport" },
        new() { Id = "wh-3", Name = "Warehouse C — Harbor" },
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_5d4d0f78b60f4a24b020e98e7b6c6c10.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit (user) gets its own instance with independent polling state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a background thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query returning a random count 0–15.
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Call when a component that needs polling becomes active.
    /// Starts polling if not already running.
    /// </summary>
    public void Subscribe()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                StartPolling();
            }
        }
    }

    /// <summary>
    /// Call when a component that needs polling is disposed/leaves.
    /// Stops polling when no subscribers remain.
    /// </summary>
    public void Unsubscribe()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                StopPolling();
            }
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on first subscribe.
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;
                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh alert data.
        _ = RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopPolling();
    }
}

